<template>
  <div class="order_search">
    <div class="order-banner" :style="{ backgroundImage: `url( ${require('@/assets/images/about_bg.jpeg')})`}">
      <div class="container">
        <h3>客戶訂單查詢</h3>
      </div>
    </div>
    <div class="container py-10">
      <div class="row jy-content-center">
        <div class="col-md-10 col-lg-4">
          <h3 class="text-title py-5 text-center f-size-m">訂單查詢</h3>
          <div class="form-control mb-10">
            <label class="mb-2" for="phone_number">手機號碼</label>
            <div class="p-relative">
              <input type="text" id="phone_number" v-model.trim="phone_number" placeholder="請輸入手機號碼">
              <div class="search" @click="searchHandler">
                <p>查詢</p>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="row jy-content-center">
        <div class="col-md-10 col-lg-6">
          <div class="order-info mb-10"  v-for="(item, index) in searchOrder" :key="index + 1">
            <h5 class="text-medium mb-2">
              <span class="title">訂單編號</span>:
              <span class="content">{{ item.id }}</span>
            </h5>
            <p class="text-medium mb-2">
              <span class="title">訂購人</span>:
              <span class="content">{{ item.user.name }}</span>
            </p>
            <p class="text-medium mb-2">
              <span class="title">地址</span>:
              <span class="content">{{ item.user.address }} {{ item.user.address_str }}</span>
            </p>
            <p class="text-medium mb-2">
              <span class="title">訂單日期</span>:
              <span class="content">{{ $filters.date(item.create_at) }}</span>
            </p>
            <p class="text-medium mb-2">
              <span class="title">付款狀態</span>:
              <span
                class="content is_paid"
                :class="{'is_paid_none': item.is_paid === false}"
              >{{ item.is_paid ? '已付款' : '未付款' }}</span>
            </p>
            <p class="text-medium mb-2">
              <span class="title">訂購品項</span>:
              <ul class="content">
                  <li v-for="p_item in item.products" :key="p_item.id">
                    {{ p_item.product.title }} {{ p_item.product.unit }} X {{ p_item.qty }}
                  </li>
              </ul>
            </p>
            <p class="text-medium mb-2">
              <span class="title">總金額</span>:
              <span class="content">${{ $filters.thColon(item.total) }}</span>
            </p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data () {
    return {
      orders: [],
      current_page: 1,
      phone_number: '', // 用於儲存輸入的手機號碼
      searchOrder: []
    }
  },
  methods: {
    searchHandler () {
      this.$emitter.emit('isLoading', true)
      this.$http
        .get(`${process.env.VUE_APP_APIURL}/api/${process.env.VUE_APP_PATH}/order?phone=${this.phone_number}`)
        .then((res) => {
          this.orders = [...res.data.orders]
          this.searchOrder = this.orders
          if (this.searchOrder.length === 0) {
            setTimeout(() => {
              this.$swal({ icon: 'error', title: '失敗', text: '找不到與此手機號碼相關的訂單' })
              this.$emitter.emit('isLoading', false)
            }, 1500)
          } else {
            setTimeout(() => {
              this.searchOrder = this.orders
              this.phone_number = ''
              this.$emitter.emit('isLoading', false)
            }, 1500)
          }
        })
        .catch((err) => {
          this.$emitter.emit('isLoading', false)
          console.dir(err)
        })
    }
  }
}
</script>

